//! dt-primitives contains types and functions that are used in both dt-core and dt-zkvm.
//! Because it is imported in the zkvm entrypoint, it should be kept minimal.

#[cfg(all(feature = "koalabear", feature = "babybear"))]
compile_error!("features `koalabear` and `babybear` are mutually exclusive");

#[cfg(all(not(feature = "koalabear"), not(feature = "babybear")))]
compile_error!(
    "dt-primitives: enable exactly one of `koalabear` or `babybear` (default: koalabear)"
);

#[cfg(all(feature = "ext5", feature = "babybear"))]
compile_error!("feature `ext5` (quintic trinomial extension) requires `koalabear`");

use lazy_static::lazy_static;
use p3_baby_bear::{BabyBear, DiffusionMatrixBabyBear};
use p3_field::{AbstractField, PrimeField32};
use p3_koala_bear::{DiffusionMatrixKoalaBear, KoalaBear};

// KoalaBear Poseidon2 internal linear layer constants from p3_koala_bear.
pub use p3_koala_bear::{
    MONTY_INVERSE as MONTY_INVERSE_KOALABEAR, POSEIDON2_INTERNAL_MATRIX_DIAG_16_KOALABEAR_MONTY,
};
use p3_poseidon2::{DiffusionPermutation, Poseidon2, Poseidon2ExternalMatrixGeneral};
use p3_symmetric::Permutation;
pub mod consts;
pub mod io;
pub mod types;

/// Type alias for Sumcheck field
#[cfg(feature = "koalabear")]
pub type SCField = KoalaBear;
#[cfg(feature = "babybear")]
pub type SCField = BabyBear;

use std::array::from_fn;

const KOALA_BEAR_POSEIDON2_HALF_FULL_ROUNDS: usize = 4;
const KOALA_BEAR_POSEIDON2_PARTIAL_ROUNDS: usize = 20;
const KOALA_BEAR_POSEIDON2_WIDTH: usize = 16;

pub fn string_to_koala_bear(hex_string: String) -> KoalaBear {
    KoalaBear::from_canonical_u64(
        u64::from_str_radix(&hex_string[2..], 16).expect("Invalid KoalaBear hex string"),
    )
}

pub fn koala_bear_round_consts() -> ([[KoalaBear; 16]; 4], [KoalaBear; 20], [[KoalaBear; 16]; 4]) {
    let p3_rc16: Vec<Vec<KoalaBear>> = RC16
        .iter()
        .map(|round| round.iter().map(|elem| string_to_koala_bear(elem.clone())).collect())
        .collect();
    let p_end = KOALA_BEAR_POSEIDON2_HALF_FULL_ROUNDS + KOALA_BEAR_POSEIDON2_PARTIAL_ROUNDS;

    let beginning_full_round_constants: [[KoalaBear; KOALA_BEAR_POSEIDON2_WIDTH];
        KOALA_BEAR_POSEIDON2_HALF_FULL_ROUNDS] =
        from_fn(|i| p3_rc16[i].clone().try_into().unwrap());
    let partial_round_constants: [KoalaBear; KOALA_BEAR_POSEIDON2_PARTIAL_ROUNDS] =
        from_fn(|i| p3_rc16[i + KOALA_BEAR_POSEIDON2_HALF_FULL_ROUNDS][0]);
    let ending_full_round_constants: [[KoalaBear; KOALA_BEAR_POSEIDON2_WIDTH];
        KOALA_BEAR_POSEIDON2_HALF_FULL_ROUNDS] =
        from_fn(|i| p3_rc16[i + p_end].clone().try_into().unwrap());

    (beginning_full_round_constants, partial_round_constants, ending_full_round_constants)
}

