pub fn runtime_poseidon2_init(
) -> Poseidon2<BabyBear, Poseidon2ExternalMatrixGeneral, DiffusionMatrixBabyBearPacthing, 24, 7> {
    const ROUNDS_F: usize = 8;
    const ROUNDS_P: usize = 21;
    let external_round_constants = RC_24_EXTERNAL_CONSTANTS.to_vec();

    let internal_round_constants = RC_24_INTERNAL_CONSTANTS.to_vec();
    Poseidon2::new(
        ROUNDS_F,
        external_round_constants,
        Poseidon2ExternalMatrixGeneral,
        ROUNDS_P,
        internal_round_constants,
        DiffusionMatrixBabyBearPacthing,
    )
}
lazy_static! {
    pub static ref POSEIDON2_INSTRUCTION: Poseidon2<BabyBear, Poseidon2ExternalMatrixGeneral, DiffusionMatrixBabyBearPacthing, 24, 7> =
        runtime_poseidon2_init();
}

