#[cfg(feature = "koalabear")]
pub fn runtime_sc_poseidon2_init(
) -> Poseidon2<KoalaBear, Poseidon2ExternalMatrixGeneral, DiffusionMatrixSCFieldPacthing, 24, 3> {
    const ROUNDS_F: usize = 8;
    const ROUNDS_P: usize = 23;
    let mut external_round_constants: Vec<[KoalaBear; 24]> =
        KB24_RC_EXTERNAL_INITIAL.iter().map(|row| row.map(KoalaBear::from_canonical_u32)).collect();
    external_round_constants
        .extend(KB24_RC_EXTERNAL_FINAL.iter().map(|row| row.map(KoalaBear::from_canonical_u32)));
    let internal_round_constants: Vec<KoalaBear> =
        KB24_RC_INTERNAL.iter().map(|v| KoalaBear::from_canonical_u32(*v)).collect();
    Poseidon2::new(
        ROUNDS_F,
        external_round_constants,
        Poseidon2ExternalMatrixGeneral,
        ROUNDS_P,
        internal_round_constants,
        DiffusionMatrixSCFieldPacthing,
    )
}

