pub fn poseidon2_init(
) -> Poseidon2<BabyBear, Poseidon2ExternalMatrixGeneral, DiffusionMatrixBabyBear, 16, 7> {
    const ROUNDS_F: usize = 8;
    const ROUNDS_P: usize = 13;
    let mut round_constants = RC_16_30.to_vec();
    let internal_start = ROUNDS_F / 2;
    let internal_end = (ROUNDS_F / 2) + ROUNDS_P;
    let internal_round_constants =
        round_constants.drain(internal_start..internal_end).map(|vec| vec[0]).collect::<Vec<_>>();
    let external_round_constants = round_constants;
    Poseidon2::new(
        ROUNDS_F,
        external_round_constants,
        Poseidon2ExternalMatrixGeneral,
        ROUNDS_P,
        internal_round_constants,
        DiffusionMatrixBabyBear,
    )
}

/// Initialize the KoalaBear Poseidon2 permutation (width=16, degree=3).
pub fn koalabear_poseidon2_init(
) -> Poseidon2<KoalaBear, Poseidon2ExternalMatrixGeneral, DiffusionMatrixKoalaBear, 16, 3> {
    const ROUNDS_F: usize = 8;
    const ROUNDS_P: usize = 20;
    let (begin_ext, partial, end_ext) = koala_bear_round_consts();
    let mut external_round_constants = begin_ext.to_vec();
    let internal_round_constants = partial.to_vec();
    external_round_constants.extend_from_slice(&end_ext);
    Poseidon2::new(
        ROUNDS_F,
        external_round_constants,
        Poseidon2ExternalMatrixGeneral,
        ROUNDS_P,
        internal_round_constants,
        DiffusionMatrixKoalaBear,
    )
}

use p3_symmetric::{CryptographicHasher, PaddingFreeSponge};

pub fn poseidon2_hash(input: Vec<BabyBear>) -> [BabyBear; 8] {
    POSEIDON2_HASHER.hash_iter(input)
}

#[cfg(feature = "babybear")]
pub fn sc_poseidon2_hash(input: Vec<BabyBear>) -> [BabyBear; 8] {
    SC_POSEIDON2_HASHER.hash_iter(input)
}

#[cfg(feature = "koalabear")]
pub fn sc_poseidon2_hash(input: Vec<KoalaBear>) -> [KoalaBear; 8] {
    SC_POSEIDON2_HASHER.hash_iter(input)
}

pub fn poseidon2_hasher() -> PaddingFreeSponge<
    Poseidon2<BabyBear, Poseidon2ExternalMatrixGeneral, DiffusionMatrixBabyBear, 16, 7>,
    16,
    8,
    8,
> {
    let hasher = poseidon2_init();
    PaddingFreeSponge::<
        Poseidon2<BabyBear, Poseidon2ExternalMatrixGeneral, DiffusionMatrixBabyBear, 16, 7>,
        16,
        8,
        8,
    >::new(hasher)
}

#[cfg(feature = "babybear")]
pub fn sc_poseidon2_hasher() -> PaddingFreeSponge<
    Poseidon2<BabyBear, Poseidon2ExternalMatrixGeneral, DiffusionMatrixBabyBear, 16, 7>,
    16,
    8,
    8,
> {
    poseidon2_hasher()
}

#[cfg(feature = "koalabear")]
pub fn sc_poseidon2_hasher() -> PaddingFreeSponge<
    Poseidon2<KoalaBear, Poseidon2ExternalMatrixGeneral, DiffusionMatrixKoalaBear, 16, 3>,
    16,
    8,
    8,
> {
    let hasher = koalabear_poseidon2_init();
    PaddingFreeSponge::<
        Poseidon2<KoalaBear, Poseidon2ExternalMatrixGeneral, DiffusionMatrixKoalaBear, 16, 3>,
        16,
        8,
        8,
    >::new(hasher)
}

