/// Append a single deferred proof to a hash chain of deferred proofs.
pub fn hash_deferred_proof(
    prev_digest: &[BabyBear; 8],
    vk_digest: &[BabyBear; 8],
    pv_digest: &[BabyBear; 32],
) -> [BabyBear; 8] {
    let mut inputs = Vec::with_capacity(48);
    inputs.extend_from_slice(prev_digest);
    inputs.extend_from_slice(vk_digest);
    inputs.extend_from_slice(pv_digest);
    poseidon2_hash(inputs.to_vec())
}

/// KoalaBear version of [`hash_deferred_proof`].
pub fn sc_hash_deferred_proof(
    prev_digest: &[SCField; 8],
    vk_digest: &[SCField; 8],
    pv_digest: &[SCField; 32],
) -> [SCField; 8] {
    let mut inputs = Vec::with_capacity(48);
    inputs.extend_from_slice(prev_digest);
    inputs.extend_from_slice(vk_digest);
    inputs.extend_from_slice(pv_digest);
    sc_poseidon2_hash(inputs.to_vec())
}
#[derive(Debug, Clone, Default)]
pub struct DiffusionMatrixBabyBearPacthing;

impl Permutation<[BabyBear; 24]> for DiffusionMatrixBabyBearPacthing {
    #[inline]
    fn permute_mut(&self, input: &mut [BabyBear; 24]) {
        let part_sum: BabyBear = input[1..].iter().cloned().sum();
        let full_sum = part_sum + input[0];

        // The first three diagonal elements are -2, 1, 2 so we do something custom.
        input[0] = part_sum - input[0];
        input[1] = full_sum + input[1];
        input[2] = full_sum + input[2].double();

        // For the remaining elements we use multiplication.
        // This could probably be improved slightly by making use of the
        // mul_2exp_u64 and div_2exp_u64 but this would involve porting div_2exp_u64 to
        // AbstractField.
        input.iter_mut().zip(INTERNAL_DIAG_MONTY_24.to_vec()).skip(3).for_each(
            |(val, diag_elem)| {
                *val = full_sum + *val * diag_elem;
            },
        );
    }
}

impl DiffusionPermutation<BabyBear, 24> for DiffusionMatrixBabyBearPacthing {}

#[derive(Debug, Clone, Default)]
pub struct DiffusionMatrixSCFieldPacthing;

#[cfg(feature = "babybear")]
fn internal_diag_monty_24(order: u32) -> [u32; 24] {
    [
        order - 2,
        1,
        2,
        (order + 1) >> 1,
        3,
        4,
        (order - 1) >> 1,
        order - 3,
        order - 4,
        order - ((order - 1) >> 8),
        order - ((order - 1) >> 2),
        order - ((order - 1) >> 3),
        order - ((order - 1) >> 4),
        order - ((order - 1) >> 7),
        order - ((order - 1) >> 9),
        order - 15,
        (order - 1) >> 8,
        (order - 1) >> 2,
        (order - 1) >> 3,
        (order - 1) >> 4,
        (order - 1) >> 5,
        (order - 1) >> 6,
        (order - 1) >> 7,
        15,
    ]
}

#[cfg(feature = "koalabear")]
fn internal_diag_monty_24(order: u32) -> [u32; 24] {
    [
        order - 2,
        1,
        2,
        (order + 1) >> 1,
        3,
        4,
        (order - 1) >> 1,
        order - 3,
        order - 4,
        order - ((order - 1) >> 8),
        order - ((order - 1) >> 2),
        order - ((order - 1) >> 3),
        order - ((order - 1) >> 4),
        order - ((order - 1) >> 5),
        order - ((order - 1) >> 6),
        order - ((order - 1) >> 24),
        (order - 1) >> 8,
        (order - 1) >> 3,
        (order - 1) >> 4,
        (order - 1) >> 5,
        (order - 1) >> 6,
        (order - 1) >> 7,
        (order - 1) >> 9,
        (order - 1) >> 24,
    ]
}

impl Permutation<[SCField; 24]> for DiffusionMatrixSCFieldPacthing {
    #[inline]
    fn permute_mut(&self, input: &mut [SCField; 24]) {
        let part_sum: SCField = input[1..].iter().cloned().sum();
        let full_sum = part_sum + input[0];

        input[0] = part_sum - input[0];
        input[1] = full_sum + input[1];
        input[2] = full_sum + input[2].double();

        let diag = internal_diag_monty_24(SCField::ORDER_U32);
        input.iter_mut().zip(diag).skip(3).for_each(|(val, diag_elem)| {
            *val = full_sum + *val * SCField::from_canonical_u32(diag_elem);
        });
    }
}

impl DiffusionPermutation<SCField, 24> for DiffusionMatrixSCFieldPacthing {}
